"use client"

import { useState, useEffect, Suspense, useRef } from "react"
import { useRouter, useSearchParams } from "next/navigation"
import { createClient } from "@/lib/supabase"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card"
import { Lock, Loader2, CheckCircle2, ShieldCheck } from "lucide-react"
import { ButtonLoader } from "@/components/button-loader"
import { SectionLoader } from "@/components/section-loader"

function SetupPasswordForm() {
  const [password, setPassword] = useState("")
  const [confirmPassword, setConfirmPassword] = useState("")
  const [loading, setLoading] = useState(false)
  const [verifying, setVerifying] = useState(true)
  const [criticalError, setCriticalError] = useState("") // Verification/Session errors
  const [formError, setFormError] = useState("") // Validation errors (mismatch, etc)
  const [success, setSuccess] = useState(false)
  const [isFirstLogin, setIsFirstLogin] = useState(true)
  
  const router = useRouter()
  const searchParams = useSearchParams()
  const hasVerified = useRef(false)

  useEffect(() => {
    const verifyCustomToken = async () => {
      if (hasVerified.current) return
      hasVerified.current = true

      const token = searchParams.get("token")
      const type = searchParams.get("type")

      if (!token) {
        setCriticalError("No security token found. Please use the link provided in your email.")
        setVerifying(false)
        return
      }

      console.log(`ResetPassword: Verifying application token...`)

      try {
        const response = await fetch('/api/auth/verify-token', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ token })
        })

        const result = await response.json()

        if (result.error) {
          console.error("ResetPassword: Verification failed:", result.error)
          const isExpired = result.error.toLowerCase().includes("expired")
          setCriticalError(
            isExpired 
              ? "This security link has expired. Please contact your administrator to revoke and re-approve your account access."
              : `Security link error: ${result.error}. Please ask your administrator to re-approve your account.`
          )
        } else {
          console.log("ResetPassword: Application token verified for", result.email)
          // Determine if first login or reset based on URL or DB state if needed
          if (type === "recovery") setIsFirstLogin(false)
        }
      } catch (err: any) {
        console.error("ResetPassword: API call failed:", err)
        setCriticalError("An unexpected error occurred during security verification.")
      } finally {
        setVerifying(false)
      }
    }

    verifyCustomToken()
  }, [searchParams])

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setLoading(true)
    setFormError("")

    if (password.length < 6) {
      setFormError("Password must be at least 6 characters.")
      setLoading(false)
      return
    }

    if (password !== confirmPassword) {
      setFormError("Passwords do not match. Please try again.")
      setLoading(false)
      return
    }

    const token = searchParams.get("token")

    try {
      const response = await fetch('/api/auth/set-password', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ token, password })
      })

      const result = await response.json()

      if (result.error) {
        setFormError(result.error)
      } else {
        setSuccess(true)
        // No need for signOut as the user was never signed in during this process
        setTimeout(() => {
          router.push("/")
        }, 2000)
      }
    } catch (err: any) {
      setFormError(err.message || "An unexpected error occurred.")
    } finally {
      setLoading(false)
    }
  }

  if (verifying) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-muted/40">
        <SectionLoader message="Verifying security token..." />
      </div>
    )
  }

  if (success) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-muted/40 p-4">
        <Card className="w-full max-w-md text-center animate-in zoom-in-95 duration-500 shadow-xl border-emerald-500/20">
          <CardHeader>
            <div className="flex justify-center mb-4">
              <div className="bg-emerald-100 dark:bg-emerald-900/30 p-3 rounded-full">
                <CheckCircle2 className="size-12 text-emerald-500" />
              </div>
            </div>
            <CardTitle className="text-2xl">Security Updated</CardTitle>
            <CardDescription className="text-base">
              Your password has been set successfully. You are being redirected to the login page to sign in with your new credentials.
            </CardDescription>
          </CardHeader>
        </Card>
      </div>
    )
  }

  return (
    <div className="flex min-h-screen items-center justify-center bg-muted/40 p-4">
      <Card className="w-full max-w-md shadow-2xl border-primary/5 overflow-hidden animate-in fade-in slide-in-from-bottom-4 duration-700">
        <div className="h-2 bg-primary" />
        <CardHeader className="space-y-2 pb-6 pt-6">
          <div className="flex justify-center mb-2">
            <div className="bg-primary/10 p-3 rounded-xl">
              <ShieldCheck className="size-8 text-primary" />
            </div>
          </div>
          <CardTitle className="text-2xl font-bold text-center">
            {isFirstLogin ? "Complete Your Account" : "Reset Your Password"}
          </CardTitle>
          <CardDescription className="text-center text-pretty">
            {isFirstLogin 
              ? "Welcome to Nexus! Please set a secure password to activate your account." 
              : "Please enter a new password for your Nexus account."}
          </CardDescription>
          
          <div className="min-h-[60px] flex items-start justify-center mt-2 px-6">
            {formError && (
              <div className="w-full p-3 text-sm text-destructive bg-background/40 backdrop-blur-sm border border-destructive/50 rounded-md animate-in fade-in duration-700">
                {formError}
              </div>
            )}
          </div>
        </CardHeader>

        <CardContent>
          {criticalError ? (
            <div className="flex flex-col gap-4">
               <div className="p-4 text-sm text-destructive bg-destructive/10 border border-destructive/20 rounded-lg text-center font-medium">
                {criticalError}
              </div>
              <Button variant="outline" onClick={() => router.push("/")} className="w-full h-11 interactive-click">
                 Return to Login
              </Button>
            </div>
          ) : (
            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="space-y-2">
                <Label htmlFor="password">New Password</Label>
                <div className="relative group">
                  <Lock className="absolute left-3 top-3 size-4 text-muted-foreground transition-colors group-focus-within:text-primary" />
                  <Input
                    id="password"
                    type="password"
                    placeholder="••••••••"
                    className="pl-10 h-11"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    required
                    disabled={loading}
                  />
                </div>
              </div>
              <div className="space-y-2">
                <Label htmlFor="confirmPassword">Confirm New Password</Label>
                <div className="relative group">
                  <Lock className="absolute left-3 top-3 size-4 text-muted-foreground transition-colors group-focus-within:text-primary" />
                  <Input
                    id="confirmPassword"
                    type="password"
                    placeholder="••••••••"
                    className="pl-10 h-11"
                    value={confirmPassword}
                    onChange={(e) => setConfirmPassword(e.target.value)}
                    required
                    disabled={loading}
                  />
                </div>
              </div>
              
              <Button type="submit" className="w-full h-11 font-semibold tracking-wide interactive-click mt-2" disabled={loading}>
                {loading ? (
                  <ButtonLoader />
                ) : (
                  isFirstLogin ? "Activate Account & Login" : "Reset Password & Login"
                )}
              </Button>
            </form>
          )}
        </CardContent>
        <CardFooter className="flex flex-col items-center gap-2 border-t bg-muted/20 py-4">
          <p className="text-xs text-muted-foreground font-medium uppercase tracking-widest opacity-60">
             Nexus System Security
          </p>
        </CardFooter>
      </Card>
    </div>
  )
}

export default function SetupPasswordPage() {
  return (
    <Suspense fallback={
      <div className="flex min-h-screen items-center justify-center bg-muted/40">
        <div className="relative size-12 flex items-center justify-center">
          <div className="absolute inset-0 rounded-full border-2 border-primary/20 border-t-primary animate-spin" />
          <div className="absolute inset-1.5 rounded-full border-2 border-secondary/20 border-b-secondary animate-[spin_1.5s_linear_infinite_reverse]" />
          <Loader2 className="size-4 text-primary animate-pulse" />
        </div>
      </div>
    }>
      <SetupPasswordForm />
    </Suspense>
  )
}
